input.command:
cd "$RUN/work"
python3 - <<'EOF'
p='index.html'; s=open(p).read()
a='  .tide-chart .now-dot {'
b='  @media (max-width: 600px) { .tide-chart .label { display: none; } }\n  .tide-chart .now-dot {'
assert s.count(a)==1; s=s.replace(a,b,1); open(p,'w').write(s)
EOF
cd /tmp/ml_verify
python3 - <<'EOF'
s=open('$RUN/work/index.html').read()
test='''<script>
var r=[];
document.querySelector('[data-filter="Field notes"]').click();
r.push('fieldnotes visible='+[...document.querySelectorAll('.post')].filter(p=>!p.hidden).length, document.getElementById('filter-count').textContent);
document.querySelector('[data-filter="Freelancing"]').click();
r.push('freelancing visible='+[...document.querySelectorAll('.post')].filter(p=>!p.hidden).length);
document.querySelector('[data-filter="all"]').click();
r.push('all visible='+[...document.querySelectorAll('.post')].filter(p=>!p.hidden).length);
var t0=document.documentElement.dataset.theme; document.querySelector('.theme-toggle').click();
r.push('theme '+t0+'->'+document.documentElement.dataset.theme+' bg='+getComputedStyle(document.body).backgroundColor);
document.querySelector('.menu-toggle').click();
r.push('menu expanded='+document.querySelector('.menu-toggle').getAttribute('aria-expanded')+' navdisplay='+getComputedStyle(document.getElementById('site-nav')).display);
document.getElementById('email').value='bad'; document.querySelector('.btn').click();
r.push('bad email: '+document.getElementById('form-msg').textContent);
document.getElementById('email').value='a@b.se'; document.querySelector('.btn').click();
r.push('good email: '+document.getElementById('form-msg').textContent);
r.push('overflow='+(document.documentElement.scrollWidth-window.innerWidth));
document.body.setAttribute('data-test', r.join(' | '));
</script></body>'''
open('t.html','w').write(s.replace('</body>',test))
EOF
C="/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"
for w in 1440 500; do "$C" --headless=new --disable-gpu --window-size=$w,900 --virtual-time-budget=3000 --dump-dom file:///tmp/ml_verify/t.html 2>/dev/null | grep -o 'data-test="[^"]*"'; done

